// Unpack the top 10 articles into individual items for the loop
var data = $('Prepare Presentation').first().json;
var articles = data.articles || [];

return articles.map(function(a) {
  var urlStr = a.url || '';
  var urlHash = 0;
  for (var ch = 0; ch < urlStr.length; ch++) {
    urlHash = ((urlHash << 5) - urlHash + urlStr.charCodeAt(ch)) | 0;
  }
  var shortHash = Math.abs(urlHash).toString(36).substring(0, 8);

  return {
    json: {
      title: a.title,
      url: a.url,
      category: a.category,
      header_score: a.header_score,
      source_count: a.source_count || 1,
      feed_name: a.feed_name,
      short_hash: shortHash,
      approve_cb: 'a:' + shortHash,
      skip_cb: 's:' + shortHash
    }
  };
});
